package com.vanigam.clothing;
import java.util.*;
import java.io.*;
import java.util.zip.*;
import org.json.*;
public final class Excel {
 public static final class Sheet {public String name;public List<Object[]> rows=new ArrayList<>();public Sheet(String name,Object... headers){this.name=name;rows.add(headers);}public void row(Object... v){rows.add(v);}}
 static String esc(Object v){return String.valueOf(v==null?"":v).replaceAll("[\\x00-\\x08\\x0B\\x0C\\x0E-\\x1F]","").replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
 static String col(int n){String s="";for(n++;n>0;n=(n-1)/26)s=(char)('A'+(n-1)%26)+s;return s;}
 static void entry(ZipOutputStream z,String name,String body)throws Exception{z.putNextEntry(new ZipEntry(name));z.write(body.getBytes("UTF-8"));z.closeEntry();}
 public static void write(OutputStream stream,List<Sheet> sheets)throws Exception{try(ZipOutputStream z=new ZipOutputStream(stream)){
  String types="<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/><Override PartName=\"/xl/styles.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml\"/>";
  String wb="<workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets>",rels="<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">";
  for(int i=0;i<sheets.size();i++){Sheet sh=sheets.get(i);int id=i+1;types+="<Override PartName=\"/xl/worksheets/sheet"+id+".xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/>";wb+="<sheet name=\""+esc(sh.name)+"\" sheetId=\""+id+"\" r:id=\"rId"+id+"\"/>";rels+="<Relationship Id=\"rId"+id+"\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet"+id+".xml\"/>";
   StringBuilder x=new StringBuilder("<worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetViews><sheetView workbookViewId=\"0\"><pane ySplit=\"1\" topLeftCell=\"A2\" activePane=\"bottomLeft\" state=\"frozen\"/></sheetView></sheetViews><cols>");int cols=sh.rows.get(0).length;for(int c=0;c<cols;c++)x.append("<col min=\"").append(c+1).append("\" max=\"").append(c+1).append("\" width=\"").append(c==1?30:20).append("\" customWidth=\"1\"/>");x.append("</cols><sheetData>");
   for(int r=0;r<sh.rows.size();r++){x.append("<row r=\"").append(r+1).append("\">");Object[] row=sh.rows.get(r);for(int c=0;c<row.length;c++){Object v=row[c];String cell=col(c)+(r+1);if(v instanceof Number)x.append("<c r=\"").append(cell).append("\"><v>").append(v).append("</v></c>");else x.append("<c r=\"").append(cell).append("\" s=\"").append(r==0?1:0).append("\" t=\"inlineStr\"><is><t xml:space=\"preserve\">").append(esc(v)).append("</t></is></c>");}x.append("</row>");}x.append("</sheetData>");if(sh.rows.size()>1)x.append("<autoFilter ref=\"A1:").append(col(cols-1)).append(sh.rows.size()).append("\"/>");x.append("</worksheet>");entry(z,"xl/worksheets/sheet"+id+".xml",x.toString());
  }
  entry(z,"[Content_Types].xml",types+"</Types>");entry(z,"_rels/.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>");entry(z,"xl/workbook.xml",wb+"</sheets></workbook>");entry(z,"xl/_rels/workbook.xml.rels",rels+"<Relationship Id=\"styles\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles\" Target=\"styles.xml\"/></Relationships>");
  entry(z,"xl/styles.xml","<styleSheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><fonts count=\"2\"><font><sz val=\"11\"/><name val=\"Calibri\"/></font><font><b/><color rgb=\"FFFFFFFF\"/><sz val=\"11\"/><name val=\"Calibri\"/></font></fonts><fills count=\"3\"><fill><patternFill patternType=\"none\"/></fill><fill><patternFill patternType=\"gray125\"/></fill><fill><patternFill patternType=\"solid\"><fgColor rgb=\"FF10233F\"/><bgColor indexed=\"64\"/></patternFill></fill></fills><borders count=\"1\"><border/></borders><cellStyleXfs count=\"1\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\"/></cellStyleXfs><cellXfs count=\"2\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\" xfId=\"0\"/><xf numFmtId=\"0\" fontId=\"1\" fillId=\"2\" borderId=\"0\" xfId=\"0\" applyFill=\"1\" applyFont=\"1\"/></cellXfs><cellStyles count=\"1\"><cellStyle name=\"Normal\" xfId=\"0\" builtinId=\"0\"/></cellStyles></styleSheet>");
 }}
 public static double rupees(long p){return p/100.0;}
 static boolean within(JSONObject o,String from,String to){String day=o.optString("day");return day.compareTo(from)>=0&&day.compareTo(to)<=0;}
 static String username(JSONObject s,String id){try{return Core.find(s.getJSONArray("users"),id).getString("name");}catch(Exception e){return id;}}
 public static List<Sheet> report(JSONObject s,String type,String from,String to)throws Exception{
  if(!from.matches("[0-9]{4}-[0-9]{2}-[0-9]{2}")||!to.matches("[0-9]{4}-[0-9]{2}-[0-9]{2}")||from.compareTo(to)>0)throw new Exception("Choose a valid date range.");List<Sheet> out=new ArrayList<>();boolean all=type.equals("backup");
  if(all||type.equals("bills")||type.equals("dashboard")){Sheet sh=new Sheet("Bills","Invoice","Date","Cashier","Mobile","Subtotal Rs","Discount Rs","Points discount Rs","Tax included Rs","Total Rs","Cash Rs","UPI Rs","Card Rs","Change Rs","Points earned","Points used");Sheet lines=new Sheet("Bill lines","Invoice","Code","Product","Size","Colour","Qty","Price Rs","Line total Rs","Unit cost Rs");JSONArray bs=s.getJSONArray("bills");for(int i=0;i<bs.length();i++){JSONObject b=bs.getJSONObject(i);if(!within(b,from,to))continue;sh.row("C-"+b.getLong("number"),b.getString("time"),b.getString("cashier"),b.getString("mobile"),rupees(b.getLong("subtotal")),rupees(b.getLong("discount")),rupees(b.getLong("reward")),rupees(b.getLong("tax")),rupees(b.getLong("total")),rupees(b.getLong("cash")),rupees(b.getLong("upi")),rupees(b.getLong("card")),rupees(b.getLong("change")),b.getLong("earned"),b.getLong("redeem"));for(int j=0;j<b.getJSONArray("lines").length();j++){JSONObject l=b.getJSONArray("lines").getJSONObject(j);lines.row("C-"+b.getLong("number"),l.getString("sku"),l.getString("name"),l.getString("size"),l.getString("colour"),l.getLong("qty"),rupees(l.getLong("price")),rupees(l.getLong("amount")),rupees(l.getLong("cost")));}}out.add(sh);out.add(lines);}
  if(all||type.equals("products")||type.equals("stock")){Sheet sh=new Sheet("Products and current stock","Code","Product","Size","Colour","Selling Rs","Cost Rs","Stock","Alert","Active","Stock value Rs");JSONArray ps=s.getJSONArray("products");for(int i=0;i<ps.length();i++){JSONObject p=ps.getJSONObject(i);sh.row(p.getString("sku"),p.getString("name"),p.getString("size"),p.getString("colour"),rupees(p.getLong("price")),rupees(p.getLong("cost")),p.getLong("stock"),p.getLong("alert"),p.getBoolean("active")?"Yes":"No",rupees(p.getLong("stock")*p.getLong("cost")));}out.add(sh);}
  if(all||type.equals("stockreport")){Sheet sh=new Sheet("Stock movements","Date","Code","Product","Type","Qty change","Unit cost Rs","Value Rs","User","Reference");Sheet summary=new Sheet("Stock period","Code","Product","Opening qty","Purchased","Sold","Wasted","Closing qty");Map<String,long[]> agg=new HashMap<>();JSONArray ms=s.getJSONArray("movements");for(int i=0;i<ms.length();i++){JSONObject m=ms.getJSONObject(i);long[] a=agg.get(m.getString("product"));if(a==null){a=new long[5];agg.put(m.getString("product"),a);}long q=m.getLong("qty");String day=m.getString("day"),kind=m.getString("type");if(day.compareTo(from)<0)a[0]+=q;else if(day.compareTo(to)<=0){if(kind.equals("Sale"))a[2]-=q;else if(kind.equals("Wastage"))a[3]-=q;else a[1]+=q;}if(within(m,from,to))sh.row(m.getString("time"),m.getString("sku"),m.getString("name"),kind,q,rupees(m.getLong("cost")),rupees(m.getLong("value")),username(s,m.getString("user")),m.getString("note"));}JSONArray ps=s.getJSONArray("products");for(int i=0;i<ps.length();i++){JSONObject p=ps.getJSONObject(i);long[] a=agg.get(p.getString("id"));if(a==null)a=new long[5];summary.row(p.getString("sku"),p.getString("name"),a[0],a[1],a[2],a[3],a[0]+a[1]-a[2]-a[3]);}out.add(summary);out.add(sh);}
  if(all||type.equals("collection")||type.equals("opening")){Sheet sh=new Sheet("User collections","Date","User","Bills","Cash Rs","UPI Rs","Card Rs","Opening cash Rs","Cash expenses Rs","Expected drawer Rs");Map<String,long[]> rows=new TreeMap<>();for(String key:new String[]{"bills","openings","expenses"}){JSONArray ar=s.getJSONArray(key);for(int i=0;i<ar.length();i++){JSONObject v=ar.getJSONObject(i);if(!within(v,from,to))continue;String k=v.getString("day")+"|"+v.getString("user");long[] a=rows.get(k);if(a==null){a=new long[6];rows.put(k,a);}if(key.equals("bills")){a[0]++;a[1]+=v.getLong("cash");a[2]+=v.getLong("upi");a[3]+=v.getLong("card");}else if(key.equals("openings"))a[4]+=v.getLong("amount");else if(v.getString("method").equals("Cash"))a[5]+=v.getLong("amount");}}for(Map.Entry<String,long[]> r:rows.entrySet()){String[] k=r.getKey().split("\\|");long[] a=r.getValue();sh.row(k[0],username(s,k[1]),a[0],rupees(a[1]),rupees(a[2]),rupees(a[3]),rupees(a[4]),rupees(a[5]),rupees(a[4]+a[1]-a[5]));}out.add(sh);}
  if(all||type.equals("top")){Sheet sh=new Sheet("Best sellers","Code","Product","Size","Colour","Qty sold","Gross line sales Rs");Map<String,JSONObject> map=new HashMap<>();JSONArray bs=s.getJSONArray("bills");for(int i=0;i<bs.length();i++){JSONObject b=bs.getJSONObject(i);if(!within(b,from,to))continue;JSONArray ls=b.getJSONArray("lines");for(int j=0;j<ls.length();j++){JSONObject l=ls.getJSONObject(j),r=map.get(l.getString("id"));if(r==null){r=new JSONObject(l.toString());r.put("qty",0).put("amount",0);map.put(l.getString("id"),r);}r.put("qty",r.getLong("qty")+l.getLong("qty")).put("amount",r.getLong("amount")+l.getLong("amount"));}}List<JSONObject> ranked=new ArrayList<>(map.values());ranked.sort((a,b)->Long.compare(b.optLong("qty"),a.optLong("qty")));for(JSONObject p:ranked)sh.row(p.getString("sku"),p.getString("name"),p.getString("size"),p.getString("colour"),p.getLong("qty"),rupees(p.getLong("amount")));out.add(sh);}
  if(all||type.equals("pl")){long sales=0,tax=0,cost=0,expense=0,waste=0;JSONArray bs=s.getJSONArray("bills");for(int i=0;i<bs.length();i++){JSONObject b=bs.getJSONObject(i);if(within(b,from,to)){sales+=b.getLong("total");tax+=b.getLong("tax");cost+=b.getLong("cost");}}for(int i=0;i<s.getJSONArray("expenses").length();i++){JSONObject e=s.getJSONArray("expenses").getJSONObject(i);if(within(e,from,to))expense+=e.getLong("amount");}for(int i=0;i<s.getJSONArray("movements").length();i++){JSONObject m=s.getJSONArray("movements").getJSONObject(i);if(within(m,from,to)&&m.getString("type").equals("Wastage"))waste-=m.getLong("value");}Sheet sh=new Sheet("Profit and loss","Metric","Amount Rs");sh.row("Net sales excluding tax",rupees(sales-tax));sh.row("Cost of sold products",rupees(cost));sh.row("Gross profit",rupees(sales-tax-cost));sh.row("Expenses",rupees(expense));sh.row("Stock wastage",rupees(waste));sh.row("Operating profit estimate",rupees(sales-tax-cost-expense-waste));out.add(sh);}
  if(all||type.equals("customers")){Sheet sh=new Sheet("Customer points","Mobile","Name","Current points");for(int i=0;i<s.getJSONArray("customers").length();i++){JSONObject c=s.getJSONArray("customers").getJSONObject(i);sh.row(c.getString("mobile"),c.getString("name"),c.getLong("points"));}out.add(sh);Sheet ledger=new Sheet("Points ledger","Date","Mobile","Bill","Earned","Used","Balance");for(int i=0;i<s.getJSONArray("points").length();i++){JSONObject p=s.getJSONArray("points").getJSONObject(i);if(within(p,from,to))ledger.row(p.getString("day"),p.getString("mobile"),p.getLong("bill"),p.getLong("earned"),p.getLong("used"),p.getLong("balance"));}out.add(ledger);}
  if(all){Sheet sh=new Sheet("Expenses","Date","User","Method","Amount Rs","Note");for(int i=0;i<s.getJSONArray("expenses").length();i++){JSONObject e=s.getJSONArray("expenses").getJSONObject(i);sh.row(e.getString("day"),username(s,e.getString("user")),e.getString("method"),rupees(e.getLong("amount")),e.getString("note"));}out.add(sh);Sheet users=new Sheet("Users","Name","Administrator","Active");for(int i=0;i<s.getJSONArray("users").length();i++){JSONObject u=s.getJSONArray("users").getJSONObject(i);users.row(u.getString("name"),u.getBoolean("admin")?"Yes":"No",u.getBoolean("active")?"Yes":"No");}out.add(users);Sheet state=new Sheet("Restore data","Chunk","Base64 JSON - do not edit");String data=java.util.Base64.getEncoder().encodeToString(s.toString().getBytes("UTF-8"));for(int i=0;i<data.length();i+=30000)state.row(i/30000,data.substring(i,Math.min(data.length(),i+30000)));out.add(state);}
  if(out.isEmpty())throw new Exception("Unknown report.");return out;
 }
}
